describe('Multi-step Form Progress Indicator', () => {
    beforeEach(() => {
        cy.visit('/multi-step-form');
    });

    it('should display the progress indicator on the first step', () => {
        cy.get('.progress-indicator').should('be.visible');
        cy.get('.progress-indicator').should('contain', 'Step 1 of 3');
    });

    it('should update the progress indicator when moving to the next step', () => {
        cy.get('input[name="firstName"]').type('John');
        cy.get('input[name="lastName"]').type('Doe');
        cy.get('button.next-step').click();

        cy.get('.progress-indicator').should('be.visible');
        cy.get('.progress-indicator').should('contain', 'Step 2 of 3');
    });
});
